Q=[]
def q(topic,title,text,opts,ans,exp,stem=None):
    d=dict(topic=topic,title=title,q=text,opts=opts,ans=ans,exp=exp)
    if stem: d['stem']=stem
    Q.append(d)
q('1.1','סוגי בינה מלאכותית','התאימו בין כל סוג של טכנולוגיית בינה מלאכותית (1–4) לבין התיאור הנכון שלה (A–D):',['1D, 2B, 3A, 4C','1D, 2C, 3B, 4A','1C, 2B, 3D, 4A','1B, 2D, 3A, 4C'],[3],'בינה סימבולית מבוססת חוקים (B); למידת מכונה קלאסית דורשת בחירת מאפיינים (D); למידה עמוקה לומדת מאפיינים אוטומטית ברשתות נוירונים (A); בינה יוצרת מייצרת נתונים חדשים (C).',
  stem=['בינה מלאכותית סימבולית (Symbolic AI)','למידת מכונה קלאסית (Classical Machine Learning)','למידה עמוקה (Deep Learning)','בינה מלאכותית יוצרת (Generative AI)','A — משתמשת ברשתות נוירונים כדי ללמוד באופן אוטומטי מאפיינים מתוך הנתונים','B — משתמשת במערכות מבוססות חוקים כדי לחקות קבלת החלטות אנושית','C — משתמשת בלמידה עמוקה כדי ליצור נתונים חדשים על בסיס הנתונים שעליהם אומנה','D — משתמשת בגישה מבוססת נתונים הדורשת בחירת מאפיינים (Feature Selection)'])
q('1.1','חלון ההקשר','בהקשר של מודלי שפה גדולים (LLMs), איזו מהאפשרויות הבאות מסבירה בצורה הטובה ביותר מדוע מגבלות חלון ההקשר (Context Window) משפיעות על יכולת עיבוד הטקסט של המודל?',['משום שחלון ההקשר מגביל את רצף העיבוד בזמן, ולכן המודל אינו מסוגל לשמור על עקביות כרונולוגית לאורך טקסטים ארוכים','משום שחלון ההקשר מונע יכולת לבצע הצלבה בין מקורות מידע שונים בו-זמנית','משום שחלון ההקשר מאלץ את המודל לשכוח מידע מוקדם יותר, אשר עשוי להיות חיוני להבנת המשך הטקסט','משום שחלון ההקשר מגביל את רמת הפירוק (Granularity) של הטקסט, ולכן המודל אינו מסוגל לעבור בין ניתוח ברמת התו לניתוח ברמת המסמך'],[2],'חלון ההקשר מגביל את מספר הטוקנים שהמודל "רואה" בבת אחת — מידע שחורג ממנו נשכח, גם אם הוא חיוני להמשך.')
q('1.1','Tokenization','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר את תהליך ה-Tokenization בעת עיבוד טקסט עבור מודלי שפה גדולים (LLMs)?',['Tokenization ממיר טוקנים לווקטורים מרובי ממדים כדי לייצג את משמעותם','Tokenization יוצר את יחידות הבניין (Tokens) שבהן משתמש המודל לצורך הבנת טקסט ויצירתו','Tokenization מייצר תשובות המתאימות להקשר באמצעות רשתות נוירונים','Tokenization חוזה את הטוקן הבא ברצף על בסיס קשרים שנלמדו'],[1],'Tokenization מפרק את הטקסט ליחידות בסיס (טוקנים). המרה לווקטורים היא Embedding, וחיזוי הטוקן הבא הוא תפקיד המודל עצמו.')
q('1.1','סוגי מודלים','בהקשר של בדיקות תוכנה, אילו מההיגדים הבאים (1–5) לגבי מודלי Foundation, מודלים מכווני הוראות (Instruction-tuned) ומודלי Reasoning הם נכונים?',['1 ו-3','2 ו-4','1, 2 ו-5','4 ו-5'],[3],'מודלי Reasoning מצטיינים בניתוח מורכב כמו דוחות תקלות ותעדוף בדיקות (4), ומודלים מכווני הוראות מצטיינים במשימות לפי הנחיה ומבנה מוגדר, כמו Gherkin (5).',
  stem=['מודלי Foundation מצטיינים ביצירת מקרי בדיקה מתוך דרישות ברמה גבוהה ללא צורך בקלט מובנה','מודלי Reasoning מצטיינים ביצירת סקריפטי בדיקה הפועלים לפי תבניות ארגוניות מוגדרות מראש','מודלים מכווני הוראות מצטיינים בתעדוף אוטונומי של הרצת בדיקות על בסיס משוב משתמשים בזמן אמת','מודלי Reasoning מצטיינים בניתוח מידע מדוחות תקלות לצורך זיהוי מגמות ותעדוף מאמצי הבדיקות','מודלים מכווני הוראות מצטיינים ביצירת מקרי בדיקה העומדים בתחביר של שפת Gherkin'])
q('1.1','Multimodal ו-Vision-Language','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר את הקשר בין Multimodal LLMs לבין Vision-Language Models?',['מודלי Multimodal הם תת-קבוצה של מודלי Vision-Language שנועדו לטפל במגוון סוגי קלט','מודלי Vision-Language הם תת-קבוצה של מודלי Multimodal המתמקדים במידע חזותי וטקסטואלי','מודלי Vision-Language אינם קשורים למודלי Multimodal ומתמקדים רק בממשק המשתמש','שני המונחים מתייחסים לאותו סוג של מודלים וניתן להשתמש בהם לסירוגין'],[1],'מודל Multimodal מעבד כמה סוגי מידע; Vision-Language הוא מקרה פרטי שלו — תמונה וטקסט.')
q('1.2','יכולות LLM בבדיקות','אילו שתי אפשרויות מבין הבאות מייצגות יכולות מרכזיות של מודלי שפה גדולים (LLMs) במשימות בדיקה?',['זיהוי עמימויות וחוסר עקביות בדרישות','יצירת קוד מלא של היישום לצורך פריסה (Deployment)','אוטומציה מלאה של הרצת כל סקריפטי הבדיקות ללא התערבות אנושית','ביצוע בדיקות אקספלורטוריות על יישומי תוכנה','יצירת נתוני בדיקה מגוונים הכוללים שילובים שונים וערכי גבול'],[0,4],'LLM מצטיין בניתוח טקסט (עמימויות בדרישות) וביצירת תוכן (נתוני בדיקה). הוא אינו מחליף פריסה, הרצה אוטונומית מלאה או בדיקות חקר אנושיות.')
q('1.2','צ׳אטבוטים מול יישומי LLM','איזו מהאפשרויות הבאות מסבירה בצורה הטובה ביותר את ההבדל בין צ׳אטבוטים מבוססי AI לבין יישומי בדיקות מבוססי LLM?',['צ׳אטבוטים מתאימים יותר למשימות בדיקה ייעודיות, בעוד שיישומי בדיקות מבוססי LLM מיועדים לאינטראקציות אד-הוק','שני הסוגים מיועדים לבצע בדיוק את אותן משימות ללא כל הבדל בתצורה','יישומי בדיקות מבוססי LLM פועלים באמצעות פרומפטים שיחתיים, בעוד שצ׳אטבוטים דורשים אינטגרציה עם כלי ותהליכי בדיקה','צ׳אטבוטים מספקים ממשק שיחתי למשימות בדיקה אד-הוק, בעוד שיישומי בדיקות מבוססי LLM מספקים פתרונות מותאמים למשימות בדיקה ייעודיות'],[3],'צ׳אטבוט — שיחה גמישה למשימות אד-הוק; יישום LLM ייעודי — משולב בכלים ובתהליכים ומותאם למשימה מוגדרת.')
q('2.1','מבנה הפרומפט','בודק תוכנה בונה פרומפט מובנה כדי לקבל סיוע מ-LLM בניתוח בדיקות ביצועים. אחד מרכיבי הפרומפט כולל את הטקסט: "דוחות מכלי בדיקות ביצועים, יומני ניטור מערכת בתקופות עומס שיא, ומדדי ביצועים של היישום מגרסאות קודמות." באיזה מרכיב מתוך מבנה הפרומפט בן שישה החלקים סביר ביותר שיופיע תיאור זה?',['הקשר (Context)','נתוני קלט (Input Data)','אילוצים (Constraints)','פורמט הפלט (Output Format)'],[1],'דוחות, יומנים ומדדים הם החומר שהמודל צריך לנתח — כלומר נתוני הקלט של הפרומפט.')
q('2.1','פורמט הפלט','בודק תוכנה מעוניין ש-LLM יכתוב מסמך דרישות ויזהה פגמים אפשריים. בפרומפט המובנה שבו הוא משתמש מופיעה השורה: "יש להציג את הפגמים האפשריים בטבלת Markdown הכוללת את העמודות הבאות: מזהה, הפניה לדרישה, סוג הפגם, תיאור וחומרה." לאיזה רכיב במבנה הפרומפט בן ששת החלקים שייכת שורה זו?',['הוראות (Instructions)','אילוצים (Constraints)','פורמט הפלט (Output Format)','הקשר (Context)'],[2],'השורה מגדירה איך התשובה תיראה — טבלת Markdown ועמודותיה — כלומר פורמט הפלט.')
q('2.1','טכניקות פרומפט','איזו מהאפשרויות הבאות מבדילה בצורה הטובה ביותר בין הטכניקות Prompt Chaining, Few-Shot Prompting ו-Meta Prompting?',['Prompt Chaining מתמקד במתן דוגמאות, Few-Shot מפרק משימות לתת-משימות, ו-Meta Prompting משפר פרומפטים באופן ידני','Few-Shot Prompting מספק הנחיה באמצעות דוגמאות, Prompt Chaining מפרק משימות למספר פרומפטים, ו-Meta Prompting מאפשר למודל לשפר באופן איטרטיבי את הפרומפטים של עצמו','Meta Prompting מתמקד בפירוק משימות לשלבים, Prompt Chaining משתמש בדוגמאות, ו-Few-Shot Prompting מתמקד באופטימיזציה ידנית של פרומפטים','Prompt Chaining מספק הנחיה ללא דוגמאות, Few-Shot Prompting מספק הנחיה באמצעות דוגמאות, ו-Meta Prompting מסתמך על פרומפטים שהוגדרו מראש על ידי הבודק'],[1],'Few-Shot = דוגמאות; Prompt Chaining = שרשרת פרומפטים לתת-משימות; Meta Prompting = המודל עוזר לנסח ולשפר את הפרומפט עצמו.')
q('2.1','System Prompt','מהו התפקיד העיקרי של System Prompt בעת אינטראקציה עם מודלי שפה גדולים (LLMs)?',['להגדיר את מסגרת ההתנהגות של ה-LLM לאורך כל השיחה','לספק ל-LLM שאלות או הוראות ספציפיות מצד המשתמש','להשתנות באופן דינמי בכל אינטראקציה עם המשתמש ולהגדיר את הקשר השיחה','לכלול את הקלט הגלוי של המשתמש ולהגדיר את כללי השיחה'],[0],'ה-System Prompt קובע תפקיד, סגנון וכללים קבועים לכל השיחה. השאלות הספציפיות הן ה-User Prompt.')
q('2.2','Prompt Chaining','הוטל עליך ליישם את גישת הבדיקות הבאה עבור סט דרישות יציב בפרויקט חדש: יצירת תנאי בדיקה (Test Conditions), תעדוף לפי רמת הסיכון וזיהוי פערי כיסוי אפשריים. הדרישות כבר נסקרו ביסודיות ולא נמצאו בהן פגמים. איזה מרצפי השלבים הבאים (1–5) יש לבצע כדי ליישם בצורה היעילה ביותר את השימוש ב-Prompt Chaining באמצעות Generative AI?',['1, 2 ו-3','2 ו-4','1, 3 ו-5','4 ו-5'],[0],'הרצף 1 ← 2 ← 3 תואם בדיוק את שלושת שלבי הגישה: יצירה, תעדוף ובדיקת כיסוי. אין צורך לחפש אי-עקביות (5) כי הדרישות כבר נסקרו.',
  stem=['שלח את הדרישות ל-LLM ובקש ממנו להפיק תנאי בדיקה המבוססים עליהן','ספק ל-LLM את תנאי הבדיקה, ודא שהוא מבין את ההקשר לצורך התעדוף, ובקש ממנו לתעדף אותם בהתאם','ספק ל-LLM את תנאי הבדיקה המתועדפים ובקש ממנו לנתח האם כל היבטי הדרישות מכוסים באמצעות תנאי הבדיקה','שלח את הדרישות ל-LLM ובקש ממנו להפיק תנאי בדיקה מתועדפים המכסים את כל היבטי הדרישות','שלח את הדרישות ל-LLM ובקש ממנו לזהות בהן אי-עקביות ועמימות'])
q('2.2','Few-Shot Structured Prompting','נניח שאתם משתמשים בטכניקת Few-Shot Structured Prompting כדי ליצור מקרי בדיקה בסגנון Gherkin עבור סיפור המשתמש "כמשתמש, אני רוצה לאפס את הסיסמה שלי כדי שאוכל לחזור לחשבון במקרה ששכחתי אותה", עם קריטריון הקבלה "כאשר משתמש מזין כתובת דוא״ל רשומה, עליו לקבל הודעת דוא״ל לאיפוס הסיסמה". לרשותכם דוגמאות מוכנות של סיפורי משתמש, קריטריוני קבלה ומקרי בדיקה ב-Gherkin. איזה מהפרומפטים הבאים הוא המתאים ביותר?',['Prompt A — Role: מנתח בדיקות; משתמש בדוגמאות המוכנות כמדריך; Constraints: Best Practices; Output: מקרי בדיקה עם תוצאות צפויות','Prompt B — Role: מנתח בדיקות המתמחה ב-Gherkin; משתמש בדוגמאות המוכנות; Constraints: תחביר Given-When-Then והתאמה מלאה לקריטריון הקבלה; Output: פורמט הדוגמאות','Prompt C — Role: מנתח בדיקות; בלי דוגמאות, נשען על Best Practices; Constraints: Given-When-Then והתאמה לקריטריון; Output: פורמט שניתן','Prompt D — Role: מנתח בדיקות; "צור לפחות שני מקרי בדיקה" עם התמקדות במקרי קצה, בלי דוגמאות; Constraints: Given-When-Then; Output: פורמט שניתן'],[1],'רק Prompt B משלב את כל מרכיבי Few-Shot Structured Prompting: תפקיד ממוקד, הדוגמאות המוכנות, אילוצי תחביר Gherkin והתאמה מלאה לקריטריון, ופורמט פלט לפי הדוגמאות. C ו-D אינם Few-Shot (אין דוגמאות).')
q('2.2','שיפור פרומפט רגרסיה','התבקשת להשתמש ב-Structured Prompting לצורך ניתוח תוצאות של בדיקות רגרסיה. טיוטת הפרומפט: Role — פעל כמנתח בדיקות · Context — נתח את תוצאות בדיקות הרגרסיה הגולמיות מהרצת הבדיקות האחרונה · Instruction — זהה אי-התאמות בתוצאות · Input Data — הקובץ המצורף · Constraints — השתמש ברשימת החריגות הידועות לצורך הצלבה · Output Format — הצג את אי-ההתאמות בטבלה. איזה מהשיפורים הבאים תואם בצורה הטובה ביותר את עקרונות Structured Prompt Engineering להפקת דוח רגרסיה מקיף?',['הוסף שלב המקבץ תקלות דומות ומבצע הצלבה מול רשימת החריגות הידועות','הגדר שהתפקיד הוא מנתח בדיקות רגרסיה המתמחה בהפקת תובנות מעשיות','הרחב את ההוראות כך שיכללו הפרדה בין התוצאות הצפויות לתוצאות בפועל, קיבוץ תקלות והדגשת אי-התאמות','הוסף באילוצים התייחסות לעקרונות בדיקות רגרסיה כגון Given-When-Then'],[2],'ההוראה (Instruction) היא החוליה החלשה בטיוטה — הרחבתה למשימות מפורטות (צפוי מול בפועל, קיבוץ, הדגשה) מפיקה דוח מקיף. Given-When-Then אינו קשור לניתוח רגרסיה.')
q('2.2','מדדי בדיקות לבעלי עניין','אתם משתמשים ב-LLM כדי להפיק מדדי בדיקות (התקדמות, מגמות תקלות וכיסוי) מתוך נתונים גולמיים, המוצגים גרפית עם הסברים טקסטואליים. המטרה: מדדים מדויקים, מעשיים (Actionable) וקלים להבנה עבור בעלי העניין. טיוטת הפרומפט: Role — מנהל בדיקות · Context — נתונים גולמיים מכלי הבדיקות · Instruction — הפק מדדי התקדמות, מגמות תקלות וכיסוי · Input Data — הקובץ המצורף · Constraints — תוצאה תמציתית וברורה · Output Format — לוח מחוונים (Dashboard). איזה מהשיפורים הבאים ישפר בצורה הטובה ביותר את יכולת ה-LLM להפיק מדדים מדויקים ובעלי ערך?',['ציין שהתפקיד הוא מנהל בדיקות המתמקד בתובנות מעשיות ובתמיכה בקבלת החלטות','הוסף הוראה לזהות סיכונים פוטנציאליים העולים מהמדדים, כולל הערכת השפעה ורמת עדיפות','הרחב את פורמט הפלט כך שיכלול גם סיכום בשפה פשוטה המפרש את המדדים וממליץ על הצעדים הבאים עבור בעלי העניין','הדגש באילוצים שעל הפלט להיות ברור גם לבעלי עניין שאינם טכניים, ולהימנע ככל האפשר ממונחים מקצועיים'],[2],'סיכום בשפה פשוטה עם המלצות לצעדים הבאים עונה ישירות על שתי הדרישות החסרות — מעשיות והבנה לבעלי העניין — בלי לשנות את מהות המדדים.')
q('2.2','Test Oracle','מטרתכם ליצור מקרי בדיקה עבור מערכת מבוססת AI הסובלת מבעיית Test Oracle, ולכן לא ניתן לדעת מהן התוצאות הצפויות. ברשותכם מספר קטן של מקרי בדיקה עם תוצאות צפויות ידועות, ומניתוחם זוהו כללי טרנספורמציה שניתן ליישם על כל מקרי הבדיקה. החלטתם להעביר ל-LLM את מקרי הבדיקה הקיימים, הקלט שלהם, התוצאות הצפויות, תיאור ברור של כללי הטרנספורמציה והנחיות ליצירת מקרי בדיקה חדשים באמצעות יישום מדויק של הכללים. איזו מטכניקות ה-Prompting הבאות היא המתאימה ביותר למטרה זו?',['Few-Shot Prompting','Prompt Chaining','Meta Prompting','Zero-Shot Prompting'],[0],'מעבירים למודל דוגמאות מוכנות (מקרי בדיקה עם קלט ותוצאות) כדי שילמד מהן את הדפוס — זו בדיוק Few-Shot Prompting.')
q('2.3','הערכת תוצרי GenAI','אתם משתמשים ב-Generative AI כדי לסייע בבדיקת מערכת תוכנה בתחום הבידור. המודל מייצר מקרי בדיקה עבור תרחישי אינטראקציה של משתמשים, סקריפטי בדיקה לאינטראקציה מול API ונתוני בדיקה סינתטיים לכיסוי מקרי קצה. כדי להעריך בצורה יעילה את ביצועי המודל ולשפר את הפרומפטים — איזו מבין האפשרויות הבאות משלבת בצורה הטובה ביותר מדדים ופעולות לצורך הערכה ושיפור?',['להעריך את מגוון מקרי הבדיקה כדי להבטיח כיסוי של תרחישי קלט שונים, ולהשתמש בשיעור ההצלחה של הרצת הבדיקות כדי לוודא את תקינות סקריפטי ה-API','להעריך את סקריפטי הבדיקה במדדי שלמות (Completeness) ודיוק (Accuracy), ולהשתמש במדד יעילות זמן (Time Efficiency) כדי להשוות יצירה באמצעות AI ליצירה ידנית','להתמקד במדד דיוק (Precision) לבחינת עמידת נתוני הבדיקה בדרישות, ובמדד התאמה להקשר (Contextual Fit) כדי להעריך התאמה לתרחישים ולמדוד את שיעור ההצלחה','לתת עדיפות לכל התוצרים למדדי רלוונטיות (Relevance) והתאמה להקשר (Contextual Fit), ולהוסיף מדדי גיוון (Diversity) להרחבת כיסוי מקרי הקצה'],[0],'אפשרות א מתאימה מדד לכל תוצר: גיוון למקרי הבדיקה ולתרחישי הקלט, ושיעור הצלחה בהרצה לסקריפטי ה-API — מדדים שאפשר למדוד ולפעול לפיהם.')
q('2.3','שיפור פרומפטים איטרטיבי','איזו מהטכניקות הבאות להערכת פרומפטים ולשיפורם באופן איטרטיבי מתאימה ביותר לזיהוי הסיבה לכך ש-LLM מייצר באופן עקבי מקרי בדיקה עם תוצאות צפויות הסותרות את הדרישות, ובכך מאפשרת לשפר את הפרומפט ולמנוע שגיאות דומות בעתיד?',['ניתוח הפלט','השוואת פרומפטים באמצעות A/B Testing','התאמת אורך הפרומפט ורמת הפירוט שלו','שילוב משוב משתמשים'],[0],'ניתוח הפלט חושף את דפוס השגיאה העקבי ואת מקורו — וממנו נגזר התיקון לפרומפט.')
q('3.1','Hallucination','מהי Hallucination בהקשר של פלטים המופקים על ידי מודלי שפה גדולים (LLMs)?',['שגיאה לוגית שבה המודל אינו מצליח לבצע בצורה נכונה תהליך חשיבה רב-שלבי','הטיה (Bias) בפלט של המודל הנגרמת כתוצאה מנתוני האימון','יצירת פלט שאינו רלוונטי או שאינו נכון מבחינה עובדתית עבור המשימה הנתונה','מגבלה של המודל להבין נקודות מבט שאינן באנגלית בעת יצירת מקרי בדיקה'],[2],'הזיה היא פלט שנשמע סביר אך אינו נכון עובדתית או אינו רלוונטי. שגיאת חשיבה והטיה הן סיכונים אחרים.')
q('3.1','זיהוי Hallucination','אתם משתמשים ב-Generative AI כדי ליצור מקרי בדיקה עבור אתר מסחר אלקטרוני. במסמך הפרויקט הוגדרו במפורש התכונות: ניהול עגלת קניות, שימוש בקוד הנחה, ושליחת הודעת דוא״ל לאישור הזמנה. בהתבסס על מידע זה בלבד, איזה ממקרי הבדיקה הבאים שנוצרו על ידי AI הוא בסבירות הגבוהה ביותר ל-Hallucination?',['לוודא שהמשתמש יכול להוסיף מספר מוצרים לעגלת הקניות ולהמשיך לתהליך התשלום','לוודא שלא ניתן להשתמש בקוד הנחה שפג תוקפו במהלך התשלום','לוודא שלאחר השלמת ההזמנה המשתמש מקבל הודעת אישור בדוא״ל','לוודא שהמשתמש יכול ליצור רשימת משאלות (Wishlist) לשמירת מוצרים מועדפים'],[3],'רשימת משאלות לא מופיעה בשום מקום במסמך — המודל "המציא" תכונה שאינה קיימת.')
q('3.1','קלט מובנה','איזו מהאפשרויות הבאות מתארת יתרון הקשור באופן הישיר ביותר לשימוש במבנה קלט ברור ומסודר בעת עבודה עם LLMs במשימות בדיקות?',['מסייע להפחית את המאמץ הנדרש לביצוע Fine-Tuning של ה-LLM','מסייע ל-LLM להפיק תוצאות פחות עמומות (Ambiguous)','מסייע ל-LLM להפיק תוצאות רלוונטיות יותר להקשר','מסייע ל-LLM להפיק תוצאות יצירתיות יותר'],[1],'קלט ברור ומובנה מצמצם פרשנויות אפשריות — ולכן מפחית עמימות בפלט.')
q('3.1','Temperature','איזו אסטרטגיה יכולה להפחית את השונות (Variability) בתוצאות בדיקה שמפיק LLM באמצעות צמצום התפלגות ההסתברויות במהלך תהליך ההסקה (Inference)?',['הגדלת קצב הלמידה (Learning Rate)','הקטנת ערך ה-Temperature','הגדלת ערך ה-Random Seed','הקטנת ערך ה-Random Seed'],[1],'Temperature נמוך מחדד את התפלגות ההסתברויות והפלט נעשה עקבי יותר. Learning Rate שייך לאימון, ו-Seed לא "מצמצם" התפלגות.')
q('3.2','פרטיות מידע','איזו מהטענות הבאות בנוגע לסיכוני פרטיות מידע בעת שימוש ב-Generative AI לצורך בדיקות תוכנה היא אינה נכונה?',['Generative AI עלול לחשוף בטעות מידע רגיש באמצעות הפלט שהוא מייצר','כלי Generative AI עשויים לשמור ולעבד מידע רגיש גם ללא הסכמה מפורשת של המשתמש, ובכך לגרום לשימוש לרעה במידע','שימוש בכלי Generative AI ללא עמידה בתקנות הגנת מידע כגון GDPR עלול לגרום להליכים משפטיים','מודל שפה גדול צפוי לחשוף מידע רגיש אמיתי אם הוא מבצע Hallucination במהלך יצירת נתוני בדיקה סינתטיים, ללא קשר לנתונים שעליהם אומן'],[3],'הזיה היא המצאת תוכן — היא לא "חושפת" מידע אמיתי שלא היה בנתוני האימון. שאר הטענות הן סיכוני פרטיות אמיתיים.')
q('3.2','וקטור תקיפה','תוקף מחדיר תוצאות בדיקה מזויפות אל מערך האימון של LLM שנועד להמליץ על אסטרטגיות מיטביות לכיסוי בדיקות. לאיזה סוג של וקטור תקיפה (Attack Vector) מתייחס תיאור זה בצורה הטובה ביותר?',['יצירת קוד זדוני (Malicious Code Generation)','מניפולציית הקשר (Context Manipulation)','מניפולציית בקשות (Request Manipulation)','הרעלת נתונים (Data Poisoning)'],[3],'הכנסת נתונים מזויפים לנתוני האימון היא הרעלת נתונים (Data Poisoning).')
q('3.2','סוגי תקיפות על LLM','התאימו בין סוג התקיפה על LLM (1–4) לבין הדוגמה המתאימה (A–D):',['1C, 2D, 3A, 4B','1B, 2D, 3A, 4C','1D, 2C, 3B, 4A','1C, 2B, 3D, 4A'],[0],'פרומפטים ארוכים שגורמים לדליפת מפתחות API — מניפולציית הקשר (C); החלפת תמונות הייחוס בבדיקות ויזואליות — מניפולציית בקשות (D); שינוי נתוני Traceability במאגר האימון — הרעלת נתונים (A); פרומפטים שגורמים ליצירת סקריפטים עם חולשות — יצירת קוד זדוני (B).',
  stem=['מניפולציית הקשר (Context Manipulation)','מניפולציית בקשות (Request Manipulation)','הרעלת נתונים (Data Poisoning)','יצירת קוד זדוני (Malicious Code Generation)','A — תוקף משנה בזדון את הנתונים הקשורים לקישורי Traceability במאגר המשמש ל-Fine-Tuning של ה-LLM, ובכך פוגע בדיוק יצירת מקרי הבדיקה','B — תוקף יוצר פרומפטים מטעים שמובילים את ה-LLM, שאומן ליצירת סקריפטי בדיקה אוטומטיים, לייצר סקריפטים פגיעים הכוללים חולשות אבטחה נסתרות','C — תוקף מספק פרומפטים ארוכים במיוחד שנבנו באופן זדוני, הגורמים ל-LLM לחשוף בטעות מפתחות API סודיים שנשמרו מפרויקטי בדיקות קודמים','D — תוקף מחליף באופן זדוני תמונות ייחוס (Reference Screenshots) במסגרת Visual Testing המשתמשת ב-LLM, במטרה לגרום למודל להתעלם באופן עקבי מבעיות אמיתיות בממשק המשתמש במהלך בדיקות רגרסיה'])
q('3.2','טיפול בסיכוני פרטיות','איזו מהאסטרטגיות הבאות מטפלת בצורה הטובה ביותר בסיכוני פרטיות מידע בהקשר של שימוש ב-Generative AI לבדיקות תוכנה?',['שימוש במספר מודלי שפה (LLMs) לצורך הערכה והשוואה של תוצאות הבדיקות במטרה לשפר את הדיוק','החלפת נתוני בדיקה רגישים בגרסה אנונימית של אותם נתונים','מתן גישה בלתי מוגבלת לנתוני בדיקה רגישים כדי לשפר את אימון מודל הבינה המלאכותית היוצרת','ביטול ההצפנה של נתוני בדיקה רגישים כדי לפשט את תהליכי האחסון והעברת הנתונים'],[1],'אנונימיזציה של הנתונים מונעת חשיפה של מידע רגיש ושומרת על התועלת לבדיקות.')
q('3.3','צריכת אנרגיה','איזו מהאפשרויות הבאות לגבי ההשפעה של שימוש במודלי שפה גדולים (LLMs) על צריכת האנרגיה ופליטות CO₂ היא נכונה?',['משימות יצירת תמונות צורכות הרבה יותר אנרגיה ממשימות יצירת טקסט, אך מייצרות פחות פליטות CO₂','חיפושים המבוססים על Generative AI צורכים פחות אנרגיה באופן משמעותי מחיפושי אינטרנט מסורתיים, הודות לאלגוריתמים יעילים יותר','משימות יצירת תמונות צורכות הרבה יותר אנרגיה ממשימות יצירת טקסט, בשל המורכבות החישובית הגבוהה יותר שלהן','משימות יצירת טקסט צורכות מעט מאוד אנרגיה, ולכן ניתן לבצע אותן על ידי מיליוני משתמשים ללא השפעה משמעותית על צריכת האנרגיה'],[2],'יצירת תמונה דורשת חישוב כבד בהרבה מיצירת טקסט — ולכן גם אנרגיה ופליטות רבות יותר.')
q('3.4','תקנים רלוונטיים','איזה שני תקנים (או חלקים מהם) מבין הבאים הם הרלוונטיים ביותר לשימוש ב-Generative AI בתחום בדיקות התוכנה?',['ISO/IEC 25010:2023','ISO/IEC 23053:2022','ISO/IEC/IEEE 29119-2:2021','ISO/IEC 42001:2023','ISO/IEC/IEEE 29119-3:2021'],[1,3],'ISO/IEC 23053 עוסק במסגרת למערכות AI מבוססות למידת מכונה, ו-ISO/IEC 42001 במערכת ניהול AI. 25010 ו-29119 הם תקני איכות ובדיקות כלליים.')
q('4.1','רכיבי יישום LLM','איזה מהרכיבים הבאים ביישום בדיקות המבוסס על LLM אחראי לשלב את קלט המשתמש עם נתונים מובנים ונתונים בעלי דמיון סמנטי, לצורך הכנת הפרומפט שישלח ל-LLM?',['Back-end','Front-end','רכיב האימות (Authentication Component)','רכיב העיבוד שלאחר ההפקה (Post-processing Component)'],[0],'ה-Back-end מעבד את הבקשה: שולף נתונים מובנים ונתונים דומים סמנטית (למשל ממסד וקטורי), ומרכיב מהם את הפרומפט.')
q('4.1','שימוש ב-RAG','אתם בודקי תוכנה במערכת בנקאית הכוללת התחברות משתמשים, ניהול חשבונות וביצוע עסקאות מאובטחות. תיעוד המערכת, כולל מפרטי API ודרישות אבטחה, מאוחסן במסד נתונים וקטורי, ומקרי בדיקה היסטוריים מאוחסנים במסד נתונים רלציוני. המטרה: ליצור מקרי בדיקה התואמים למפרטים ולדרישות העדכניות ביותר. בתרחיש זה, איזו מהאפשרויות הבאות מתארת את השימוש המתאים ביותר במסגרת RAG?',['שלחו שאילתה שמציינת פונקציה אחת לבדיקה. מסגרת ה-RAG תשלוף ממסד הנתונים הווקטורי את המפרטים והדרישות הרלוונטיים, תשלב אותם עם מקרי הבדיקה ההיסטוריים, ותייצר באופן אוטומטי באמצעות ה-LLM מקרי בדיקה מדויקים ומודעי הקשר','שלחו שאילתה למסגרת ה-RAG הכוללת את כל הפונקציונליות שיש לבדוק. מסגרת ה-RAG תשלוף ממסד הנתונים הווקטורי את כל המפרטים, הדרישות והמידע הרלוונטיים, תשלב אותם עם מקרי הבדיקה ההיסטוריים, ולאחר מכן תנחה את ה-LLM ליצור את מקרי הבדיקה המדויקים, המקיפים והרלוונטיים ביותר לדרישות המערכת','השתמשו במסגרת ה-RAG כדי לשלוף את מקרי הבדיקה ההיסטוריים ואת דרישות האבטחה והמפרטים הרלוונטיים. לאחר מכן בצעו סקירה ידנית של המידע שנשלף, ורק לאחר מכן שפרו את השאילתה שתישלח ל-LLM','לצורך יצירת מקרי הבדיקה הסתמכו אך ורק על נתוני האימון הפנימיים של ה-LLM, והשתמשו במסגרת ה-RAG לשליפת מידע רלוונטי בלבד, מבלי לשלב אותו ביצירת מקרי הבדיקה'],[0],'RAG שולף את המידע העדכני מהמסדים, משלב אותו עם המקרים ההיסטוריים ומעביר ל-LLM כהקשר — כך מקרי הבדיקה מבוססים על המפרטים העדכניים. אפשרות א אינה עוסקת ב-RAG כלל.')
q('4.1','LLM-powered Agents','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר את התרומה של Agents אוטונומיים וחצי-אוטונומיים המבוססים על LLM לאוטומציה של תהליכי בדיקות?',['הם יכולים לשפר הן את היעילות והן את איכות תהליכי הבדיקות באמצעות שימוש מאוזן במערכות Agent יחיד ובמערכות Multi-Agent','הם יכולים לשפר את איכות תהליכי הבדיקות באמצעות הוספת מנגנוני אימות מורכבים, אך על חשבון היעילות','הם יכולים לשפר הן את היעילות והן את איכות תהליכי הבדיקות בזכות יכולתם לפעול ברמות שונות של מעורבות אנושית','הם יכולים לשפר הן את היעילות והן את איכות תהליכי הבדיקות, תוך ביטול מוחלט של הצורך בבקרה ואימות בתהליך'],[2],'הגמישות לפעול מאוטונומיה מלאה ועד מעורבות אנושית מוגדרת (Human-in-the-loop) היא שמאפשרת יעילות לצד שמירה על איכות. הם לא מבטלים לגמרי את הבקרה.')
q('4.1','Fine-Tuning','איזו מהטענות הבאות לגבי Fine-Tuning של מודלי שפה למשימות בדיקה ייעודיות היא אינה נכונה?',['Fine-Tuning כולל אימון של מודל שאומן מראש באמצעות נתונים ייעודיים למשימה, במטרה לשפר את ביצועיו ואת הידע שלו בתחום','Fine-Tuning מקנה למודל יכולות חדשות באמצעות החלפת הידע הכללי שלו ביכולת הסקה ייעודית למשימה, ובכך מבטיח שלא יתרחש Overfitting','Fine-Tuning משנה את הפרמטרים של מודל שאומן מראש באמצעות מערך נתונים ייעודי, כדי להתאים אותו לתחום או למשימה מסוימת','Fine-Tuning דורש מערכי נתונים איכותיים וספציפיים למשימה, כדי למנוע תוצאות מוטות או שגויות'],[1],'Fine-Tuning מתאים את המודל — הוא לא מחליף את הידע הכללי, ובוודאי שאינו "מבטיח" שלא יהיה Overfitting; זה בדיוק אחד הסיכונים שלו.')
q('4.2','LLMOps','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר את המטרה המרכזית של LLMOps (Large Language Model Operations) בעת פריסה וניהול של מודלי שפה גדולים לצורך משימות בדיקה?',['למנוע הסתמכות על Generative AI בתהליכי הבדיקות','לנהל את מודלי השפה לאורך כל מחזור החיים שלהם, כולל היבטי פרטיות, אבטחה ועלויות','להגביל את השימוש במודלי שפה לפתרונות מבוססי צ׳אטבוט בלבד כדי לצמצם את מורכבות המערכת','לבצע אוטומציה מלאה של כל משימות הבדיקה ללא צורך בפיקוח אנושי'],[1],'LLMOps הוא ניהול מחזור החיים של המודל בייצור — פריסה, ניטור, עדכונים, פרטיות, אבטחה ועלויות.')
q('4.2','Shadow AI','איזו מהטענות הבאות לגבי Shadow AI היא נכונה?',['Shadow AI מבטיח עמידה במדיניות הארגונית ובתקנות כלליות לשימוש בבינה מלאכותית','Shadow AI מבטל את הצורך בהסכמי רישוי ברורים עבור כלי AI','Shadow AI מפחית את הסיכון למחלוקות בנושאי קניין רוחני','Shadow AI עלול להוביל לגישה בלתי מורשית למידע רגיש'],[3],'Shadow AI הוא שימוש בכלי AI ללא אישור הארגון — ולכן עלול לחשוף מידע רגיש ולהפר מדיניות, רישוי וקניין רוחני.')
q('4.2','אסטרטגיית GenAI','מהו אחד השיקולים המרכזיים בעת הגדרת אסטרטגיית Generative AI עבור בדיקות תוכנה?',['להכין תוכניות הכשרה שמטרתן להבטיח שכל חברי הצוות יקבלו הסמכה ייעודית עבור כל LLM שבו הם משתמשים','לבחור מודלי שפה שניתן לשלב בצורה מתאימה עם סביבת הבדיקות וכלי הבדיקות הקיימים','להבטיח שכמה שיותר נתוני קלט יהיו זמינים, כדי להגדיל את הסיכוי לקבלת פלטים יעילים מה-LLM','לאסוף מדדי Machine Learning סטנדרטיים מסוג Supervised Learning לצורך הערכת איכות הפלטים של ה-LLM'],[1],'השתלבות עם הכלים והתהליכים הקיימים היא שיקול מרכזי בבחירת מודלים לאסטרטגיה.')
q('4.2','בחירת LLM','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר אחד הקריטריונים המרכזיים לבחירת LLM מתאים למשימות בדיקה בארגון?',['להעריך את ביצועי ה-LLM במשימות הבדיקה מול מדדי Benchmark ציבוריים בתחום יצירת קוד','להעריך את העלויות השוטפות, כגון עלויות המשאבים החישוביים הנדרשים להפעלת ה-LLM','להעריך את ה-LLM מול כל מדדי ה-Benchmark הציבוריים של קהילת המשתמשים, כדי להבטיח תאימות מלאה אליהם','להעריך את העלויות השוטפות של ביצוע Proof of Concept שנועד להוכיח את התאמת ה-LLM למשימות הבדיקה'],[1],'עלויות התפעול השוטפות (משאבי חישוב) הן קריטריון מרכזי. Benchmark ציבורי בתחום אחר אינו מעיד על התאמה למשימות הבדיקה של הארגון.')
q('5.1','שלבי אימוץ','מהם השלבים המרכזיים באימוץ Generative AI בארגון בדיקות?',['גילוי (Discovery), התחלה והגדרת שימוש (Initiation and Usage Definition), שימוש ואיטרציה (Utilization and Iteration)','מודעות (Awareness), תיעדוף שימושים (Usage Prioritization), ניטור ביצועים (Performance Monitoring)','תכנון (Planning), ניסויים (Experimentation), הערכה ושיפור (Evaluation and Refinement)','הכשרה (Training), בדיקות (Testing), הטמעה (Implementation) והרחבה (Scaling)'],[0],'לפי הסילבוס, האימוץ עובר שלושה שלבים: גילוי, התחלה והגדרת שימוש, ושימוש ואיטרציה.')
q('5.2','מיומנויות נדרשות','איזו מהאפשרויות הבאות היא הדוגמה הטובה ביותר לידע או למיומנות הנדרשים מבודקי תוכנה כדי לעבוד בצורה יעילה עם מודלי שפה גדולים בתהליכי בדיקה?',['שליטה בטכניקות שמטרתן למנוע ממודלי שפה לבצע הזיות (Hallucinations) ושגיאות הסקה בעת ביצוע משימות בדיקה','בחירה ויישום של גישות מתאימות לאוטומציית בדיקות, כגון Keyword-Driven Testing, לצורך אוטומציה של תהליכי בדיקה','בחירת מודל השפה המתאים ביותר בהתאם לקריטריונים כגון היכולת להתאים אותו למשימות בדיקה ספציפיות או לבצע לו התאמה אישית (Customization)','הבטחת האיכות הגבוהה ביותר של נתוני האימות (Validation Data) ונתוני הבדיקה ששימשו לפיתוח מודלי שפה'],[2],'בחירת מודל לפי התאמה למשימה היא מיומנות שהבודק צריך. אי אפשר "למנוע" הזיות לחלוטין — רק לצמצם ולזהות אותן.')
q('5.2','פיתוח יכולות הצוות','מהי הגישה הטובה ביותר לפיתוח היכולות והמיומנויות של צוותי בדיקות לצורך תמיכה באימוץ Generative AI?',['להסתמך בעיקר על קורסים מעשיים של מומחים חיצוניים, במטרה לשלב AI בכל משימות הבדיקה היומיומיות בבת אחת','לעודד ניסויים עצמאיים במגוון מודלי שפה, ללא תהליך עבודה מובנה','לאמץ תהליך למידה הדרגתי ומעשי, הנתמך בתרגול מודרך, למידת עמיתים וקהילות לשיתוף ידע','להסתמך בעיקר על קורסים תאורטיים של מומחים חיצוניים, תוך שילוב הדרגתי של AI במשימות היומיומיות בהתאם לקצב הלמידה'],[2],'למידה הדרגתית ומעשית עם תרגול מודרך, למידת עמיתים וקהילות — היא הגישה המומלצת לבניית מיומנויות לאורך זמן.')
q('5.3','שינוי תפקידים','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר כיצד אימוץ Generative AI משפיע על התפקידים והאחריות של בודקי תוכנה ומנהלי בדיקות בארגון?',['בודקי התוכנה מעבירים את עיקר המיקוד שלהם מתכנון ידני של מקרי בדיקה להנחיה, בקרה ואימות של תוצרי בדיקה שנוצרו על ידי AI','מנהלי הבדיקות מעבירים את עיקר המיקוד שלהם מניהול פרויקטי בדיקות להבנה מעמיקה של אופן הפעולה הפנימי של טכנולוגיות Generative AI','בודקי התוכנה מעבירים את עיקר המיקוד שלהם מתכנון ידני של מקרי בדיקה לפיקוח על תהליכי בדיקה מבוססי AI','מנהלי הבדיקות מעבירים את עיקר המיקוד שלהם מהסתמכות על אנשים להסתמכות בלעדית על Generative AI לצורך שיפור הפרודוקטיביות במשימות הבדיקה'],[0],'הבודק עובר מכתיבה ידנית להנחיית ה-AI ולבקרה ואימות של תוצריו — המעורבות המקצועית שלו נשארת מרכזית.')
